import { useMemo } from "react";
import { SHARED_STAT_INFO } from "../components/DpsCalc/DivineShard/DivineShardData";

const CRITICAL_DAMAGE_BONUS = 0.5; // 치명타 발생 시 추가 피해량 (50%)

export const useFinalStats = (dpsState, processedWeaponData) => {
  const finalStats = useMemo(() => {
    // 기본값 설정
    let baseDps = 0;
    let totalMps = 0;
    let totalMpr = 0;
    let finalDamageMultiplier = 1; // 최종 대미지 배율 (기본 100%)
    let totalMaxMana = 0;

    // 숫자 파싱 헬퍼 함수
    const parseNumber = (str) => {
      if (!str) return 0;
      const num = parseFloat(str);
      return isNaN(num) ? 0 : num;
    };

    // 1. 레벨 스탯 및 시너지 데이터 추출
    const {
      level = 1,
      str = 0,
      spd = 0,
      vit = 0,
      synergyBonuses = {},
    } = dpsState || {};

    // 2. 장신구 옵션 처리 (시너지 보너스와 합산)
    const accessoryStats = dpsState.accessories?.totalStats || {};
    // 장신구 수치와 시너지 수치를 합쳐주는 헬퍼
    const getCombinedStat = (displayName, synergyKey) =>
      parseNumber(accessoryStats[displayName]) +
      (synergyBonuses[synergyKey] || 0);

    const acc = {
      // DPS 메인 로직에서 별도로 계산되는 항목들 (중복 합산 방지)
      classBasicAttackDamage: parseNumber(
        accessoryStats["클래스 기본 공격 데미지 증가 +"],
      ),
      classSkillDamagePercent: parseNumber(
        accessoryStats["클래스 스킬 데미지 증가 %"],
      ),
      classBasicAttackPercent: parseNumber(
        accessoryStats["클래스 기본 공격 데미지 증가 %"],
      ),
      cooldownReductionPercent: parseNumber(
        accessoryStats["스킬 쿨타임 감소 %"],
      ),

      // 장신구 + 시너지가 즉시 통합되어야 하는 항목들
      finalDamageStat: getCombinedStat(
        "최종 데미지 스탯 증가 +",
        "finalDamageStat",
      ),
      healthStat: getCombinedStat("체력 스탯 증가 +", "healthStat"),
      normalMonsterDamagePercent: getCombinedStat(
        "일반 몬스터 대상 데미지 증가 %",
        "normalMonsterDamagePercent",
      ),
      bossMonsterDamagePercent: getCombinedStat(
        "보스 공격 시 대상 데미지 증가 %",
        "bossMonsterDamagePercent",
      ),
      specialWeaponDamagePercent: getCombinedStat(
        "특수 무기 데미지 증가 %",
        "specialWeaponDamagePercent",
      ),
      commonAdvancedWeaponDamagePercent: getCombinedStat(
        "일반&고급 등급 무기 데미지 증가 %",
        "commonAdvancedWeaponDamagePercent",
      ),
      rareWeaponDamagePercent: getCombinedStat(
        "희귀 등급 무기 데미지 증가 %",
        "rareWeaponDamagePercent",
      ),
      heroicWeaponDamagePercent: getCombinedStat(
        "영웅 등급 무기 데미지 증가 %",
        "heroicWeaponDamagePercent",
      ),
      legendaryWeaponDamagePercent: getCombinedStat(
        "전설 등급 무기 데미지 증가 %",
        "legendaryWeaponDamagePercent",
      ),
      legendaryMortalWeaponDamagePercent: getCombinedStat(
        "전설&필멸 등급 무기 데미지 증가 %",
        "legendaryMortalWeaponDamagePercent",
      ),
      mortalWeaponDamagePercent: getCombinedStat(
        "필멸 등급 무기 데미지 증가 %",
        "mortalWeaponDamagePercent",
      ),
      mythicWeaponDamagePercent: getCombinedStat(
        "신화 등급 무기 데미지 증가 %",
        "mythicWeaponDamagePercent",
      ),
      legendaryMythicWeaponDamagePercent: getCombinedStat(
        "전설&신화 등급 무기 데미지 증가 %",
        "legendaryMythicWeaponDamagePercent",
      ),
      mortalMythicWeaponDamagePercent: getCombinedStat(
        "필멸&신화 등급 무기 데미지 증가 %",
        "mortalMythicWeaponDamagePercent",
      ),
      destinyWeaponDamagePercent: getCombinedStat(
        "운명 등급 무기 데미지 증가 %",
        "destinyWeaponDamagePercent",
      ),
      maxManaFlat: getCombinedStat("최대 마나 증가 +", "maxManaFlat"),
      maxManaPercent: getCombinedStat("최대 마나 증가 %", "maxManaPercent"),
      manaRegenFlat: getCombinedStat("마나 회복량 증가 +", "manaRegenFlat"),
      manaRegenPercent: getCombinedStat(
        "마나 회복량 증가 %",
        "manaRegenPercent",
      ),
      criticalRate: getCombinedStat("치명타 확률 %", "criticalRate"),
      cooldownReductionLimitPercent: getCombinedStat(
        "쿨타임 감소 상한 증가 %",
        "cooldownReductionLimitPercent",
      ),
    };

    const s = parseInt(str, 10) || 0;
    const a = parseInt(spd, 10) || 0;
    const v = parseInt(vit, 10) || 0;
    const safeLevel = parseInt(level, 10) || 1;

    // 7. 스킬 쿨타임 감소
    const statCooldownReduction = a * 0.1;
    const baseCdLimit = 40;
    const totalCdLimit = baseCdLimit + acc.cooldownReductionLimitPercent;

    const totalCooldownReduction = Math.min(
      acc.cooldownReductionPercent +
        statCooldownReduction +
        (synergyBonuses.cooldownReductionPercent || 0),
      totalCdLimit,
    );
    const cooldownMultiplier = 1 - totalCooldownReduction / 100;

    // 1. 특수 무기 DPS 및 마나 소모 계산 (Base DPS)
    if (dpsState.specialWeapons) {
      const uniqueItems = {};
      dpsState.specialWeapons.forEach((item) => {
        if (!item.name) return;
        if (!uniqueItems[item.name] || item.enh > uniqueItems[item.name].enh) {
          uniqueItems[item.name] = item;
        }
      });

      const parseValue = (str) => {
        if (str === null || str === undefined) return null;
        if (typeof str === "number") return str;
        const num = parseFloat(str);
        return isNaN(num) ? null : num;
      };

      Object.values(uniqueItems).forEach((item) => {
        let { damage, hits, cooldown, mana, grade, breakthrough } = item;

        // Backward compatibility
        if (
          (damage === undefined || damage === null) &&
          Object.keys(processedWeaponData).length > 0
        ) {
          const weaponData = processedWeaponData[item.name];
          const weapon = weaponData?.byEnhancement[item.enh];
          if (weapon) {
            damage = weapon["피해량"];
            hits = weapon["타수"];
            cooldown = weapon["쿨타임"];
            mana = weapon["마나"];
            grade = weapon["등급"];
          }
        }

        const numDamage = parseValue(damage);
        const numHits = parseValue(hits);
        const numCooldown = parseValue(cooldown);
        const numMana = parseValue(mana);

        const breakthroughMultiplier = 1 + (breakthrough || 0) * 0.2;
        const totalDamage =
          numDamage !== null && numHits !== null
            ? numDamage * numHits * breakthroughMultiplier
            : 0;

        const effectiveCooldown =
          numCooldown > 0 ? numCooldown * cooldownMultiplier : 0;

        const dps =
          totalDamage > 0 && effectiveCooldown > 0
            ? totalDamage / effectiveCooldown
            : 0;
        const mps =
          numMana > 0 && effectiveCooldown > 0
            ? numMana / effectiveCooldown
            : 0;

        let weaponDamageMultiplier = 1 + acc.specialWeaponDamagePercent / 100;

        if (grade) {
          if (grade === "일반" || grade === "고급") {
            weaponDamageMultiplier +=
              acc.commonAdvancedWeaponDamagePercent / 100;
          }
          if (grade === "희귀") {
            weaponDamageMultiplier += acc.rareWeaponDamagePercent / 100;
          }
          if (grade === "영웅") {
            weaponDamageMultiplier += acc.heroicWeaponDamagePercent / 100;
          }
          if (grade === "전설") {
            weaponDamageMultiplier += acc.legendaryWeaponDamagePercent / 100;
            weaponDamageMultiplier +=
              acc.legendaryMortalWeaponDamagePercent / 100;
            weaponDamageMultiplier +=
              acc.legendaryMythicWeaponDamagePercent / 100;
          }
          if (grade === "필멸") {
            weaponDamageMultiplier += acc.mortalWeaponDamagePercent / 100;
            weaponDamageMultiplier +=
              acc.legendaryMortalWeaponDamagePercent / 100;
            weaponDamageMultiplier += acc.mortalMythicWeaponDamagePercent / 100;
          }
          if (grade === "운명") {
            weaponDamageMultiplier += acc.destinyWeaponDamagePercent / 100;
          }
          if (grade === "신화") {
            weaponDamageMultiplier += acc.mythicWeaponDamagePercent / 100;
            weaponDamageMultiplier +=
              acc.legendaryMythicWeaponDamagePercent / 100;
            weaponDamageMultiplier += acc.mortalMythicWeaponDamagePercent / 100;
          }
        }

        baseDps += dps * weaponDamageMultiplier;
        totalMps += mps;
      });
    }

    // 레벨 스탯 포인트 검증
    const usedPoints = s + a + v;
    const totalPoints = Math.max(0, safeLevel);
    const isOverLimit = usedPoints > totalPoints;

    let damageBonusFromStats = 0;
    let classBonus = {
      classBasicAttackDamage: 0,
      classBasicAttackPercent: 0,
      classSkillDamagePercent: 0,
    };

    // 스탯 기본 보너스 (포인트 초과 시 0)
    damageBonusFromStats = isOverLimit ? 0 : s * 0.65 + (a + v) * 0.4;

    // 클래스 보너스 (스탯분은 초과 시 0, 시너지는 항상 유지)
    classBonus = {
      classBasicAttackDamage:
        (isOverLimit ? 0 : s * 5) +
        (synergyBonuses.classBasicAttackDamage || 0),
      classBasicAttackPercent:
        (isOverLimit ? 0 : s * 0.3) +
        (synergyBonuses.classBasicAttackPercent || 0),
      classSkillDamagePercent:
        (isOverLimit ? 0 : a * 0.3) +
        (synergyBonuses.classSkillDamagePercent || 0),
    };

    // 장신구 스탯 보너스 추가 (3, 4)
    damageBonusFromStats += acc.finalDamageStat * 0.65;
    damageBonusFromStats += acc.healthStat * 0.4;

    // 길드 업그레이드 (길드원의 유대)
    const guildState = dpsState.guild || {};
    const bondLevel = parseInt(guildState.atk_percent || 1, 10);
    const bondBonusPoints = Math.max(0, bondLevel - 1);
    damageBonusFromStats += bondBonusPoints * 1 * 0.65; // 공격력 스탯
    damageBonusFromStats += bondBonusPoints * 1 * 0.4; // 체력 스탯

    // 디바인 샤드
    let shardFinalDamagePercent = 0;
    let shardMaxManaFlat = 0;
    let shardManaRegenFlat = 0;

    if (dpsState.divineShard) {
      Object.values(dpsState.divineShard).forEach((shard) => {
        if (!shard.stats) return;
        shard.stats.forEach((level, index) => {
          if (level <= 0) return;
          const statInfo = SHARED_STAT_INFO[index];
          if (!statInfo) return;

          if (statInfo.name === "최종 데미지 증가") {
            shardFinalDamagePercent += statInfo.effects[0].values[level] || 0;
          } else if (statInfo.name === "최대 마나 & 마나 회복량 증가") {
            shardMaxManaFlat += statInfo.effects[0].values[level] || 0;
            shardManaRegenFlat += statInfo.effects[1].values[level] || 0;
          }
        });
      });
    }

    // 최종 대미지 배율에 합산
    finalDamageMultiplier +=
      (damageBonusFromStats +
        shardFinalDamagePercent +
        (synergyBonuses.finalDamagePercent || 0)) /
      100;

    // 마나 계산
    // 최대 마나: 기본 100, 5레벨마다 5 증가
    const baseMaxManaFromLevel = 100 + Math.floor(safeLevel / 5) * 5;
    // 마나 회복량: 기본 4, 5레벨마다 0.05 증가
    const manaRegenFromLevel = 4 + Math.floor(safeLevel / 5) * 0.05;

    totalMaxMana =
      (baseMaxManaFromLevel + acc.maxManaFlat + shardMaxManaFlat) *
      (1 + acc.maxManaPercent / 100);
    totalMpr =
      (manaRegenFromLevel + acc.manaRegenFlat + shardManaRegenFlat) *
      (1 + acc.manaRegenPercent / 100);

    // 3. 클래스 스탯 계산
    if (dpsState.classStats) {
      const { classStats } = dpsState;
      const skills = [
        { name: "좌클릭", damageKey: "좌클릭 피해량", cdKey: "좌클릭 쿨타임" },
        { name: "우클릭", damageKey: "우클릭 피해량", cdKey: "우클릭 쿨타임" },
        {
          name: "쉬프트 좌클릭",
          damageKey: "쉬프트 좌클릭 피해량",
          cdKey: "쉬프트 좌클릭 쿨타임",
        },
        {
          name: "쉬프트 우클릭",
          damageKey: "쉬프트 우클릭 피해량",
          cdKey: "쉬프트 우클릭 쿨타임",
        },
      ];

      skills.forEach((skill) => {
        let damage = parseNumber(classStats[skill.damageKey]);
        const cooldown = parseNumber(classStats[skill.cdKey]);
        const effectiveCooldown =
          cooldown > 0 ? cooldown * cooldownMultiplier : 0;

        if (damage > 0 && effectiveCooldown > 0) {
          let skillDps = 0;
          if (skill.name === "좌클릭") {
            // 1. 클래스 기본 공격 데미지 증가 (+ 및 %)
            damage =
              (damage +
                acc.classBasicAttackDamage +
                classBonus.classBasicAttackDamage) *
              (1 +
                (acc.classBasicAttackPercent +
                  classBonus.classBasicAttackPercent) /
                  100);
            skillDps = damage / effectiveCooldown;
          } else {
            // 2. 클래스 스킬 데미지 증가
            damage *=
              1 +
              (acc.classSkillDamagePercent +
                classBonus.classSkillDamagePercent) /
                100;
            skillDps = damage / effectiveCooldown;
          }
          baseDps += skillDps;
        }
      });
    }

    // 최종 DPS 계산 (모든 배율 적용)
    // 치명타 배율 계산 (기대값 방식: 1 + 확률 * 추가피해)
    const criticalMultiplier =
      1 + (Math.max(0, acc.criticalRate) / 100) * CRITICAL_DAMAGE_BONUS;

    const finalDps = baseDps * finalDamageMultiplier * criticalMultiplier;

    const totalDpsVsNormal =
      finalDps * (1 + acc.normalMonsterDamagePercent / 100);
    const totalDpsVsBoss = finalDps * (1 + acc.bossMonsterDamagePercent / 100);
    const totalDpmVsNormal = totalDpsVsNormal * 60;
    const totalDpmVsBoss = totalDpsVsBoss * 60;

    return {
      totalDps: finalDps,
      totalDpsVsNormal,
      totalDpsVsBoss,
      totalDpm: finalDps * 60,
      totalDpmVsNormal,
      totalDpmVsBoss,
      totalMps,
      totalMpr,
      totalMaxMana,
    };
  }, [dpsState, processedWeaponData]);

  return finalStats;
};
